{
  "category": "identifiers",
  "items": [
    {
      "id": "acer_code",
      "label": "ACER Code",
      "comment": "Unique identifier for participants in the European wholesale energy market, used for regulatory reporting, ensuring transparency, and monitoring market integrity under rules like REMIT (Regulation on Energy Market Integrity and Transparency). It's an alphanumeric code assigned during registration for trading and reporting energy transactions across the EU.",
      "regex": "^[A-Z0-9]{8,11}\\.[A-Z]{2}$"
    },
    {
      "id": "aer_free_zone_license",
      "label": "UAE DAFZ Primary License Number",
      "comment": "Primary license number of free zone establishment in Dubai",
      "regex": "^\\d+$"
    },
    {
      "id": "aer_free_zone_reg_no",
      "label": "UAE DAFZ Register Number",
      "comment": "Registration number for Dubai free zone",
      "regex": "^\\d+$"
    },
    {
      "id": "aer_ner_number",
      "label": "UAE National Economic Register ID Number",
      "comment": "Unique registration number. Assigned to every company registered with the UAE National Economic Register.",
      "regex": "^\\d{8}$"
    },
    {
      "id": "afg_business_license",
      "label": "Afghanistan Business License Code",
      "comment": "Afghanistan natural and legal person business license ID code",
      "regex": "^[A-Za-z]{1}-[0-9]{5}$"
    },
    {
      "id": "afg_passport",
      "label": "Afghanistan Passport",
      "comment": "Afghanistan passport number",
      "regex": "^\\w{0,2}-?\\s?\\d{5,}$"
    },
    {
      "id": "afg_trade_internal_shipment_id",
      "label": "Afghanistan Trade Internal Shipment ID",
      "comment": "Afghanistan Trade Internal Shipment ID",
      "regex": "^[\\dA-Z]+$"
    },
    {
      "id": "afghan_tin_number",
      "label": "Afghanistan TIN",
      "comment": "Afghanistan tax ID number",
      "regex": "^[0-9]{10}$"
    },
    {
      "id": "ago_matricula_number",
      "label": "Angola Matricula No.",
      "comment": "Angola company registration number",
      "regex": "^\\d[\\d\\.\\/\\\\\\-]+\\d(\\-?[Gg][Oo])?$"
    },
    {
      "id": "ago_nif_number",
      "label": "Angola NIF",
      "comment": "Angola taxpayer number",
      "regex": "^\\d[\\dA-Z]+\\d$"
    },
    {
      "id": "alb_registration_number",
      "label": "Albania Registration Number",
      "regex": "^\\D{2}-\\d{6}-\\d{2}-\\d+$"
    },
    {
      "id": "alb_tax_id",
      "label": "Albania NUIS Number",
      "comment": "Albania tax ID number",
      "regex": "^\\D\\d{8}\\D$"
    },
    {
      "id": "alberta_corporation_number",
      "label": "CAN Alberta Corporation Number",
      "comment": "Unique Canada province ID number. Assigned to every legal entity in the Alberta Corporate Registry.",
      "regex": "^\\d{9,10}$"
    },
    {
      "id": "alei",
      "label": "Authoritative Legal Entity Identifier",
      "comment": "Authoritative legal entity identifier (ALEI), a government-issued registration number that is standardized according to [ISO 8000](https://en.wikipedia.org/wiki/ISO_8000)",
      "regex": "^[\\w\\-\\.]+:\\d+$"
    },
    {
      "id": "are_difc_reg_no",
      "label": "UAE DIFC Registered Number",
      "comment": "Dubai International Financial Centre registration number",
      "regex": "^\\d{4}$"
    },
    {
      "id": "are_dubai_land_case_no",
      "label": "Dubai Rental Disputes Center Case No.",
      "comment": "Case number for Dubai land cases",
      "regex": "^\\d{11}$"
    },
    {
      "id": "are_reg_auth_number",
      "label": "Abu Dhabi Registration Authority Number",
      "comment": "Abu Dhabi Registration Authority Number",
      "regex": "^\\d+$"
